(() => {
  const check = (actual, expected) => {
    if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error('结果不符合预期');
  };
  const source = [1, 2, 3, 4, 5];
  check(pageWindow(source, 2, 2), { page: 2, totalPages: 3, items: [3, 4] });
  check(pageWindow(source, 99, 2), { page: 3, totalPages: 3, items: [5] });
  check(pageWindow(source, 0, 2), { page: 1, totalPages: 3, items: [1, 2] });
  check(pageWindow(source, Number.MIN_SAFE_INTEGER, 2), { page: 1, totalPages: 3, items: [1, 2] });
  check(pageWindow(source, Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER), { page: 1, totalPages: 1, items: source });
  check(pageWindow([1, 2, 3, 4], 2, 2), { page: 2, totalPages: 2, items: [3, 4] });
  check(pageWindow(source, 5, 1), { page: 5, totalPages: 5, items: [5] });
  check(source, [1, 2, 3, 4, 5]);
  const result = pageWindow(Object.freeze(source), 1, 10);
  if (result.items === source) throw new Error('应返回新数组');
})();

