(() => {
  const expectRangeError = (fn) => {
    try { fn(); } catch (error) {
      if (error instanceof RangeError) return;
      throw error;
    }
    throw new Error('应抛出 RangeError');
  };
  for (const size of [0, -1, 1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, '2', null, undefined, true, 2n]) {
    expectRangeError(() => pageWindow([], 1, size));
  }
  for (const page of [1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, Number.MIN_SAFE_INTEGER - 1, '1', null, undefined, true, 1n]) {
    expectRangeError(() => pageWindow([], page, 2));
  }
})();
